define("OutSystemsUI_2_23.controller$LayoutReady.RunOnStartJS", [], function () {
return function ($parameters, $actions, $roles, $public) {
// Actions that run only once per application start

if(window.applicationStarted === undefined) {
    $actions.SetDeviceClass($parameters.IsWebApp);

    if($parameters.IsWebApp || $parameters.IsPWA) {
        $actions.ECTCall();  
        $actions.WCAGMetaTag();
    }
    
    // Call the "Built with OutSystems" label for Reactive Web apps
    var showMWO = false;
    
    try {
        showMWO = $public.Branding.showOutSystemsWatermark();
    } catch(e) {
        
    }
    
    $actions.RequireScript($parameters.URL).then(function(){
        if(showMWO && $parameters.IsWebApp) {
            osui.StartMWO();
        }
    });
    
    window.applicationStarted = true;
} else if($parameters.IsWebApp === false) {
    // Add again orientation event, removed on the Layout OnDestroy
    OutSystems.OSUI.Utils.LayoutPrivate.OnOrientationChange.Set();
}
};
});
define("OutSystemsUI_2_23.controller$LayoutReady.SetA11YAttrsJS", [], function () {
return function ($actions, $roles, $public) {
const setA11YAttrs = OutSystems.OSUI.Utils.LayoutPrivate.SetA11Y;
if(setA11YAttrs) {
    setA11YAttrs.Set();
}
};
});
